from pathlib import Path
import json,numpy as np,struct,hashlib
P=Path(__file__).resolve().parent;rows=[]
for p in sorted((P/'parts').glob('*.stl')):
 b=p.read_bytes();t=np.array([struct.unpack_from('<12fH',b,84+i*50)[3:12]for i in range(struct.unpack_from('<I',b,80)[0])]).reshape(-1,3,3);cr=np.cross(t[:,1]-t[:,0],t[:,2]-t[:,0]);sq=(cr*cr).sum(1)
 for i in np.where(sq<1e-15)[0]:rows.append({'file':str(p.relative_to(P)),'triangle_index':int(i),'area_mm2':float(np.sqrt(sq[i])/2),'cross_squared_mm4':float(sq[i]),'exact_zero':bool(sq[i]==0),'vertices':t[i].tolist()})
(P/'MICRO-TRIANGLE-RISK.json').write_text(json.dumps({'status':'REMAINING_MICRO_TRIANGLES_NOT_PRINT_CERTIFIED','count':len(rows),'criterion':'cross_squared < 1e-15 mm4, separate from nonzero topology','triangles':rows,'two_coplanar_pairs_retriangulated_without_vertex_motion':True,'remaining_five_not_blindly_deleted':True},indent=2)+'\n')
q=json.load(open(P/'BINARY-QA.json'));c=json.load(open(P/'ASSEMBLY-COLLISION-QA.json'));f=json.load(open(P/'SOURCE-FRONT-SYMMETRIC-DIFFERENCE.json'));b=json.load(open(P/'SOURCE-BOUNDARY-DISTANCE.json'));m=json.load(open(P/'ACTUAL-FACE-RGB-VERIFICATION-1303.json'))
a={'status':'BOUNDED_DIGITAL_RESEARCH_NOT_PHYSICAL_FIT_OR_PRINT_APPROVAL','parts':len(q['parts']),'triangles':sum(x['triangles']for x in q['parts']),'part_topology_status':q['status'],'all_pairs':c['all_pairs'],'positive_AABB_candidates':c['broadphase_candidates'],'intersection_detection_threshold_mm3':c['positive_volume_detection_threshold_mm3'],'intersections_above_threshold':len(c['positive_intersections']),'raw_max_intersection_mm3':max(x['volume_mm3']for x in c['all_candidate_volumes']),'not_exact_zero_claim':True,'source_front_symmetric_difference_max_mm2':max(x['symmetric_difference_area_mm2']for x in f['results']),'source_boundary_report':'SOURCE-BOUNDARY-DISTANCE.json','actual_material_status':m['status'],'micro_triangles_retained':len(rows),'unproven':['physical insertion','retention/connectors','structural stability','material shrinkage','physical print','minimum manufacturable edge thickness','complete asbuilt appearance'],'unknown_RF_domains_unbuilt':True,'artificial_joint_design':{'proxy_corner_and_roof_gable_depth_ratio':.98,'source_gables_prioritized_over_proxy_walls':8,'platform_notches':3,'nominal_wall_and_roof_back_mm':.8,'minimum_thickness_at_source_edge':'tends to zero; not a printable minimum guarantee'},'geometry_scope':'Nominal design reconstruction with bounded walls and neutral whole mixed opening proxies; not a building survey.'}
(P/'DIGITAL-QA.json').write_text(json.dumps(a,indent=2)+'\n')
